package cn.coursecompass.app;
public class WidgetStyleCheck {
 public static void main(String[] args){WidgetStyle glass=new WidgetStyle("bad","bad",null,"javascript:alert(1)",1);if(!glass.style.equals("glass")||!glass.content.equals("course")||!glass.accent.equals("#368bc1")||glass.opacity!=40)throw new AssertionError("invalid defaults");WidgetStyle clock=new WidgetStyle("pixel","date","hello","#ff0000",95),record=new WidgetStyle("record","quote","hello","#0000ff",500);if(!clock.content.equals("date")||record.opacity!=100||clock.background()==record.background())throw new AssertionError("style isolation");if((clock.background()>>>24)!=242||(record.background()>>>24)!=255)throw new AssertionError("opacity");if(clock.foreground()==glass.foreground())throw new AssertionError("contrast");if(new WidgetStyle("record","quote","x".repeat(90),"#123456",90).quote.length()!=60)throw new AssertionError("quote bounds");System.out.println("PASS widget styles: isolated content, colors, alpha, bounds and contrast");}
}
